package view;

import bus.billing.BillingBUS;
import java.awt.*;
import java.math.BigDecimal;
import java.time.format.DateTimeFormatter;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import model.auth.AuthenticatedSession;
import model.billing.BillingModels.*;
import view.component.UIStyle;

final class BillingPanel extends JPanel {
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");
    private final AuthenticatedSession session; private final BillingBUS bus; private final boolean paymentMode;
    private final JTextField search=new JTextField(); private final JComboBox<String> filter=new JComboBox<>(new String[]{"Tất cả trạng thái","ChuaThanhToan","ThanhToanMotPhan","DaThanhToan","DaHuy","DaHoanTien"});
    private final JLabel stats=new JLabel("Đang tải..."); private final DefaultTableModel model=new DefaultTableModel(new Object[]{"Mã HĐ","Số hóa đơn","Bệnh nhân","Ngày lập","Tổng tiền","Đã thu","Còn phải thu","Trạng thái","__row"},0){public boolean isCellEditable(int r,int c){return false;}}; private final JTable table=new JTable(model); private final JButton pay=new JButton("Ghi nhận thanh toán");
    BillingPanel(AuthenticatedSession s,BillingBUS b,boolean mode){session=s;bus=b;paymentMode=mode;if(mode)filter.setSelectedIndex(1);setLayout(new BorderLayout(0,16));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(25,28,30,28));add(header(),BorderLayout.NORTH);add(body(),BorderLayout.CENTER);load();}
    private JPanel header(){JPanel p=new JPanel(new BorderLayout(12,0));p.setOpaque(false);JPanel labels=new JPanel();labels.setOpaque(false);labels.setLayout(new BoxLayout(labels,BoxLayout.Y_AXIS));JLabel t=new JLabel(paymentMode?"Thanh toán":"Quản lý hóa đơn");t.setFont(new Font("Segoe UI",Font.BOLD,25));t.setForeground(MainFrame.TEXT);JLabel d=new JLabel(paymentMode?"Ghi nhận tiền thu và theo dõi công nợ theo từng hóa đơn.":"Tra cứu hóa đơn, số tiền đã thu và số tiền còn phải thu.");d.setForeground(MainFrame.MUTED);labels.add(t);labels.add(d);p.add(labels,BorderLayout.WEST);p.add(stats,BorderLayout.EAST);return p;}
    private JPanel body(){JPanel p=new JPanel(new BorderLayout(0,12));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(16,16,16,16)));JPanel bar=new JPanel(new BorderLayout(8,0));bar.setOpaque(false);search.setPreferredSize(new Dimension(320,36));search.putClientProperty("JTextField.placeholderText","Tìm số hóa đơn, mã bệnh nhân, họ tên...");UIStyle.field(search);bar.add(search,BorderLayout.CENTER);filter.setPreferredSize(new Dimension(150,36));JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,7,0));actions.setOpaque(false);JButton refresh=new JButton("Làm mới");UIStyle.secondaryButton(refresh);refresh.addActionListener(e->load());UIStyle.primaryButton(pay);pay.setEnabled(false);pay.addActionListener(e->openPayment());actions.add(filter);actions.add(refresh);actions.add(pay);bar.add(actions,BorderLayout.EAST);table.setRowHeight(40);UIStyle.table(table);table.setAutoCreateRowSorter(true);table.getSelectionModel().addListSelectionListener(e->pay.setEnabled(paymentMode&&table.getSelectedRow()>=0));p.add(bar,BorderLayout.NORTH);p.add(new JScrollPane(table),BorderLayout.CENTER);search.addActionListener(e->load());filter.addActionListener(e->load());return p;}
    private InvoiceRow selected(){int r=table.getSelectedRow();if(r<0)return null;return (InvoiceRow)table.getValueAt(table.convertRowIndexToModel(r),8);}
    private void openPayment(){InvoiceRow row=selected();if(row==null)return;if(row.remaining().compareTo(BigDecimal.ZERO)<=0){UIStyle.showInfo(this,"Hóa đơn này đã thanh toán đủ.");return;}JTextField amount=new JTextField(row.remaining().toPlainString()),ref=new JTextField(),note=new JTextField();JComboBox<PaymentMethod> method=new JComboBox<>();try{for(PaymentMethod m:bus.methods(session))method.addItem(m);}catch(RuntimeException e){UIStyle.showError(this,e.getMessage());return;}JPanel form=new JPanel(new GridLayout(0,2,8,8));form.add(new JLabel("Còn phải thu"));form.add(new JLabel(money(row.remaining())));form.add(new JLabel("Số tiền thu *"));form.add(amount);form.add(new JLabel("Phương thức *"));form.add(method);form.add(new JLabel("Mã tham chiếu"));form.add(ref);form.add(new JLabel("Ghi chú"));form.add(note);if(UIStyle.showFormDialog(this,form,"Ghi nhận thanh toán · "+row.number(),new Dimension(480,260))!=JOptionPane.OK_OPTION)return;try{bus.pay(session,new PaymentDraft(row.id(),((PaymentMethod)method.getSelectedItem()).id(),new BigDecimal(amount.getText().trim()),ref.getText(),note.getText()));UIStyle.showSuccess(this,"Đã ghi nhận thanh toán thành công.");load();}catch(RuntimeException e){UIStyle.showError(this,e.getMessage());}}
    private void load(){new SwingWorker<java.util.List<InvoiceRow>,Void>(){protected java.util.List<InvoiceRow> doInBackground(){String st=filter.getSelectedIndex()==0?"":(String)filter.getSelectedItem();return paymentMode?bus.paymentQueue(session,search.getText(),st):bus.invoices(session,search.getText(),st);}protected void done(){try{model.setRowCount(0);for(InvoiceRow r:get())model.addRow(new Object[]{r.id(),r.number(),r.patientId()+" - "+r.patientName(),r.issuedAt().format(DATE),money(r.total()),money(r.paid()),money(r.remaining()),r.status(),r});stats.setText("Tổng: "+model.getRowCount()+" hóa đơn");table.getColumnModel().getColumn(8).setMinWidth(0);table.getColumnModel().getColumn(8).setMaxWidth(0);table.getColumnModel().getColumn(8).setWidth(0);}catch(Exception e){UIStyle.showError(BillingPanel.this,e.getCause()==null?e.getMessage():e.getCause().getMessage());}}}.execute();}
    private static String money(BigDecimal n){return n==null?"0":n.stripTrailingZeros().toPlainString();}
}
